head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > columnEllipsis]<br/>아이템 리스트창에 아이템의 라벨값이 모두 표시되지 않을때 '...' 줄임표를 표시할지 설정합니다.",
    "validation" : [                
        "visibleColNum 또는 visibleColMax 속성을 설정한 경우도 columnEllipsis 속성이 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {    
        submenuSize : "fixed",
        visibleColNum : 2,
        columnEllipsis : con_columnEllipsis.getText(),
    };

    let cList = $c.gcm.createCList(properties);    

    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    $c.gcm.createLabel('label="true 설정 시 item 의 class 에 w2table_ccb_col_label_ellipsis 설정되면 정상"', '', 'label1');

    strTarget += '<xf:checkcombobox ' + strNameSpace + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_Item">';
    strTarget += '<xf:label ref="label"></xf:label>';
    strTarget += '<xf:value ref="value"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:checkcombobox>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "checkcombobox",
        strTarget,
        grp_comp
    ); 

    target1.setValue(1);
}



scwin.btn_getItemClass_onclick = function (e) {
    let comp = "target1_itemTable";
    let targetElements = document.querySelectorAll('[id*='+comp+']');

    if (targetElements.length == 0)
            wf_body_bottom.getObj("scwin").setReturnValue("CheckComboBox 의 아이템 리스트를 한번 오픈해야 아이템 리스트 정보를 가져올 수 있음");

    // 그 요소 내의 모든 label 태그를 선택
    let labels = document.getElementsByTagName('label');

    // 각 label을 반복하며 내용을 확인
    for (let i = 0; i < labels.length; i++) {
        wf_body_bottom.getObj("scwin").setReturnValue("index="+ i +" 인 item 의 className : " + labels[i].className);
    }

    scwin.getCompClass();
};



scwin.getCompClass = function (e) {
    // 클래스를 가진 요소를 선택
    let element = document.querySelector('.w2checkcombobox_label');

    // 요소의 computed style 가져오기
    let computedStyle = window.getComputedStyle(element);

    // text-overflow 값 가져오기
    let textOverflowValue = computedStyle.getPropertyValue('text-overflow');

    wf_body_bottom.getObj("scwin").setReturnValue("component 의 text-overflow : " + textOverflowValue);
}
